package tree

import "fmt"

type Record struct {
	ID     int
	Parent int
}

type Node struct {
	ID       int
	Children []*Node
}

// Build reconstructs the tree from an unsorted set of records.
//
// The root record has ID 0 and Parent 0. Every other record must
// reference a parent with a strictly lower ID. Build returns an error
// if the records are invalid: duplicate or missing IDs, a missing or
// malformed root, or a parent that is not lower than the child.
// Children are returned sorted by ID.
func Build(records []Record) (*Node, error) {
	if len(records) == 0 {
		return nil, nil
	}

	nodes := make([]*Node, len(records))
	parents := make([]int, len(records))
	hasRoot := false

	for _, record := range records {
		if record.ID < 0 || record.ID >= len(records) {
			return nil, fmt.Errorf("record ID %d is out of range", record.ID)
		}
		if nodes[record.ID] != nil {
			return nil, fmt.Errorf("duplicate record ID %d", record.ID)
		}
		if record.ID == 0 {
			if record.Parent != 0 {
				return nil, fmt.Errorf("root record must have parent ID 0, got %d", record.Parent)
			}
			hasRoot = true
		} else if record.Parent < 0 || record.Parent >= record.ID {
			return nil, fmt.Errorf("record %d must have a parent ID lower than its own ID, got %d", record.ID, record.Parent)
		}
		nodes[record.ID] = &Node{ID: record.ID}
		parents[record.ID] = record.Parent
	}

	if !hasRoot {
		return nil, fmt.Errorf("no root record")
	}

	for id, node := range nodes {
		if node == nil {
			return nil, fmt.Errorf("missing record ID %d", id)
		}
	}

	// Because every parent ID is lower than its child's ID, attaching
	// children in ascending ID order yields them already sorted.
	for id := 1; id < len(nodes); id++ {
		nodes[parents[id]].Children = append(nodes[parents[id]].Children, nodes[id])
	}

	return nodes[0], nil
}
